// The one shell for the client apps (agents, notes, voice, dash): the sidebar (the project
// switcher in its header, the app's own navigation in its body, the collapse button and the account
// menu in its footer, the rail) and the page beside it under a header row that carries the phone's
// sidebar trigger — and ⌘K, a palette over the projects and the sidebar's pages
// (app-shell-palette.tsx). Router-agnostic on purpose:
// the app hands over hrefs and its current location, nothing from TanStack comes in here.
import {
  useCallback,
  useEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type MouseEvent,
  type ReactNode,
  type RefObject,
} from "react";
import {
  CheckIcon,
  ChevronsLeftIcon,
  ChevronsUpDownIcon,
  EyeIcon,
  LogOutIcon,
  UsersIcon,
} from "lucide-react";
import type { Principal } from "iterate/principal";
import {
  AppShellPalette,
  PaletteHeaderButton,
  PaletteSidebarButton,
  usePaletteShortcut,
} from "./app-shell-palette.tsx";
import {
  readSidebarNav,
  type AppPaletteEntry,
  type SidebarNavItem,
} from "./app-shell-palette-entries.ts";
import { plainLeftClick } from "#/lib/plain-left-click.ts";
import { Avatar, AvatarFallback } from "#/components/ui/avatar.tsx";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "#/components/ui/dropdown-menu.tsx";
import { IterateLogo } from "#/components/iterate-logo.tsx";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarRail,
  SidebarTrigger,
  useSidebar,
} from "#/components/ui/sidebar.tsx";
import { resetPosthog } from "#/components/posthog.tsx";

/** A project as the switcher lists it; `org` is its organization, when the app knows it — grouped
 *  by the id (two organizations may share a name), labelled by the name. */
export type AppShellProject = { id: string; slug: string; org?: { id: string; name: string } };

/** Nothing to subscribe to: the cookie has no change event, and `SidebarProvider` reads
 *  `defaultOpen` once, when it mounts. */
const subscribeToNothing = () => () => {};

/** Frames a signed-in page. It reads the `sidebar_state` cookie shadcn's provider writes, so the
 *  sidebar reopens the way it was left — through `useSyncExternalStore`, which keeps the read out
 *  of render: a server render (no page frames itself here under SSR today) gets shadcn's default,
 *  open. */
export function AppShell({
  app,
  projects,
  activeProjectId,
  projectHref,
  onNavigate,
  switcherActions,
  nav,
  paletteEntries,
  header,
  account,
  accountActions,
  locationKey,
  children,
}: {
  /** the app's name, on top of the switcher: "Agents", "Notes", "Voice" */
  app: string;
  /** the projects this session lists; grouped by `org` when the app names one */
  projects: AppShellProject[];
  activeProjectId: string | null;
  /** where the app shows a project (`/projects/<slug>` by convention) — a same-origin href;
   *  switching is a full navigation unless
   *  `onNavigate` takes it (an app with a client router prevents the default and navigates itself).
   *  Only a plain left click is handed over: a modified or middle click keeps the anchor's own
   *  behaviour (a new tab). */
  projectHref: (project: AppShellProject) => string;
  onNavigate?: (href: string, event: MouseEvent<HTMLAnchorElement>) => void;
  /** the app's own items at the end of the switcher menu — `DropdownMenuItem`s, after a separator */
  switcherActions?: ReactNode;
  /** the app's own navigation, its `SidebarGroup`s */
  nav?: ReactNode;
  /** rows for ⌘K beside what it reads off `nav`: what the sidebar shows in a way it can't read
   *  (a file tree in its own shadow DOM) */
  paletteEntries?: AppPaletteEntry[];
  /** what sits beside the phone's sidebar trigger in the header row */
  header?: ReactNode;
  /** who the app is signed in as (`info.principal`); "Sign out" posts to the SDK's `/.auth/logout`,
   *  "Switch account…" signs in again through the issuer's consent. A platform admin signed in as
   *  someone (`impersonatedBy`) sees whom and who they are, above the account menu, with Stop
   *  impersonating, which signs in again the same way (the issuer still knows them). */
  account: Principal;
  /** the app's own items in the account menu, before Sign out — `DropdownMenuItem`s */
  accountActions?: ReactNode;
  /** the router's current href — a change closes the phone's sidebar sheet */
  locationKey: string;
  children: ReactNode;
}) {
  const defaultOpen = useSyncExternalStore(
    subscribeToNothing,
    () => !document.cookie.split("; ").includes("sidebar_state=false"),
    () => true,
  );
  // the palette: the sidebar's navigation as it read when ⌘K opened it, null while closed
  const navRef = useRef<HTMLDivElement>(null);
  const [palette, setPalette] = useState<SidebarNavItem[] | null>(null);
  const openPalette = () => setPalette(readSidebarNav(navRef.current));
  usePaletteShortcut(
    useCallback(() => setPalette((open) => (open ? null : readSidebarNav(navRef.current))), []),
  );
  return (
    <SidebarProvider defaultOpen={defaultOpen} className="h-svh">
      {/* outside <Sidebar>: on a phone its children live in a Sheet that remounts when opened */}
      <CloseMobileSidebarOnNavigate locationKey={locationKey} />
      <Sidebar collapsible="icon">
        <SidebarHeader>
          <ProjectSwitcher
            app={app}
            projects={projects}
            activeProjectId={activeProjectId}
            projectHref={projectHref}
            onNavigate={onNavigate}
            actions={switcherActions}
          />
          <PaletteSidebarButton onOpen={openPalette} />
        </SidebarHeader>
        {/* ⌘K lists what the sidebar shows here — on a desktop; a phone's lists the projects alone */}
        <SidebarNav navRef={navRef}>{nav}</SidebarNav>
        <SidebarFooter>
          <CollapseButton />
          {account.impersonatedBy ? (
            <ImpersonationMarker
              email={account.email || account.actor}
              admin={account.impersonatedBy.email}
            />
          ) : null}
          <AccountMenu email={account.email || account.actor} actions={accountActions} />
        </SidebarFooter>
        <SidebarRail />
      </Sidebar>
      <SidebarInset className="min-w-0 overflow-hidden">
        <header className="flex shrink-0 items-center gap-3 px-4 pt-2.5 pb-1">
          <SidebarTrigger className="-ml-1 md:hidden" title="Toggle sidebar" />
          <PaletteHeaderButton onOpen={openPalette} />
          {header}
        </header>
        <div className="flex min-h-0 flex-1 flex-col overflow-auto">{children}</div>
      </SidebarInset>
      <AppShellPalette
        nav={palette}
        entries={paletteEntries || []}
        onClose={() => setPalette(null)}
        projects={projects}
        activeProjectId={activeProjectId}
        projectHref={projectHref}
        onNavigate={onNavigate}
      />
    </SidebarProvider>
  );
}

/** Dismiss the mobile sidebar (a Sheet) when the page navigates — shadcn's Sidebar exposes
 *  `setOpenMobile` and does not do this itself. The whole href counts, not the pathname: the apps
 *  navigate by search string (`/agents?project=…&agent=…`). Only on an actual change, never on
 *  mount: the Sheet remounts its children when opened. */
function CloseMobileSidebarOnNavigate({ locationKey }: { locationKey: string }) {
  const { setOpenMobile } = useSidebar();
  const previousLocationKeyRef = useRef(locationKey);
  useEffect(() => {
    if (previousLocationKeyRef.current === locationKey) return;
    previousLocationKeyRef.current = locationKey;
    setOpenMobile(false);
  }, [locationKey, setOpenMobile]);
  return null;
}

/** The app's navigation. On a phone, a same-tab link click in it closes the sidebar sheet at once,
 *  as the navigation starts; shadcn leaves it open (https://github.com/shadcn-ui/ui/issues/5561),
 *  and `CloseMobileSidebarOnNavigate` only fires once the location has changed. A modified or
 *  middle click, a download, or a link to another tab leaves the sheet open, as does a button (the
 *  collapse button, a dropdown trigger). This used to live in the vendored sidebar.tsx's
 *  SidebarMenuButton (#1984); a vendored file stays byte-identical to upstream
 *  (packages/ui/AGENTS.md). */
function SidebarNav({
  navRef,
  children,
}: {
  navRef: RefObject<HTMLDivElement | null>;
  children: ReactNode;
}) {
  const { isMobile, setOpenMobile } = useSidebar();
  return (
    <SidebarContent
      ref={navRef}
      onClick={(event) => {
        if (!isMobile) return;
        if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)
          return;
        const link = event.target instanceof Element ? event.target.closest("a[href]") : null;
        if (!link || !event.currentTarget.contains(link) || link.hasAttribute("download")) return;
        const target = link.getAttribute("target");
        if (target && target !== "_self") return;
        setOpenMobile(false);
      }}
    >
      {children}
    </SidebarContent>
  );
}

function ProjectSwitcher({
  app,
  projects,
  activeProjectId,
  projectHref,
  onNavigate,
  actions,
}: {
  app: string;
  projects: AppShellProject[];
  activeProjectId: string | null;
  projectHref: (project: AppShellProject) => string;
  onNavigate?: (href: string, event: MouseEvent<HTMLAnchorElement>) => void;
  actions?: ReactNode;
}) {
  const { isMobile } = useSidebar();
  // one group per organization (by id), in order of first appearance; a bare list when the app
  // names none
  const orgs = [...new Map(projects.map((project) => [project.org?.id, project.org])).values()];
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <SidebarMenuButton
                size="lg"
                className="data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground"
                aria-label="Switch project"
              >
                <span className="flex aspect-square size-8 items-center justify-center rounded-md bg-black">
                  <IterateLogo alt="" className="size-6" />
                </span>
                <span className="grid flex-1 text-left text-sm leading-tight">
                  <span className="truncate font-medium">{app}</span>
                  <span className="truncate text-xs text-muted-foreground">
                    {projects.find((project) => project.id === activeProjectId)?.slug ||
                      "(select project)"}
                  </span>
                </span>
                <ChevronsUpDownIcon className="ml-auto" />
              </SidebarMenuButton>
            }
          />
          <DropdownMenuContent
            align="start"
            side={isMobile ? "bottom" : "right"}
            sideOffset={4}
            className="min-w-60 rounded-lg"
          >
            {projects.length === 0 ? (
              <DropdownMenuItem disabled className="p-2">
                No projects yet
              </DropdownMenuItem>
            ) : null}
            {orgs.map((org) => (
              <DropdownMenuGroup key={org?.id || ""}>
                {/* Base UI: a menu label lives inside a group, never bare in the menu */}
                {org ? (
                  <DropdownMenuLabel className="text-xs text-muted-foreground">
                    {org.name}
                  </DropdownMenuLabel>
                ) : null}
                {projects
                  .filter((project) => project.org?.id === org?.id)
                  .map((project) => (
                    <DropdownMenuItem
                      key={project.id}
                      className="gap-2 p-2"
                      render={
                        <a
                          href={projectHref(project)}
                          aria-label={`Switch to ${project.slug}`}
                          onClick={
                            onNavigate
                              ? (event) => {
                                  if (!plainLeftClick(event)) return;
                                  onNavigate(projectHref(project), event);
                                }
                              : undefined
                          }
                        />
                      }
                    >
                      <span className="flex size-6 items-center justify-center rounded-md border text-xs font-medium text-muted-foreground">
                        {project.slug.slice(0, 1)}
                      </span>
                      <span className="truncate">{project.slug}</span>
                      {project.id === activeProjectId ? <CheckIcon className="ml-auto" /> : null}
                    </DropdownMenuItem>
                  ))}
              </DropdownMenuGroup>
            ))}
            {actions ? (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuGroup>{actions}</DropdownMenuGroup>
              </>
            ) : null}
          </DropdownMenuContent>
        </DropdownMenu>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

function CollapseButton() {
  const { state, toggleSidebar } = useSidebar();
  const collapsed = state === "collapsed";
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton
          type="button"
          size="sm"
          className="text-sidebar-foreground/70"
          tooltip={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          onClick={toggleSidebar}
        >
          <ChevronsLeftIcon className={collapsed ? "rotate-180" : undefined} />
          <span>Collapse sidebar</span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

/** SIGN IN AGAIN, through the issuer: the app's own logout (ends this sign-in's grant), then its
 *  login with the same permissions (app-server.ts), which finds the person still signed in at the
 *  issuer and shows its consent — where a platform admin may "Sign in as someone else…" — and lands
 *  on the app's root (not the page shown: it is often another person's project). */
const SIGN_IN_AGAIN = `/.auth/logout?${new URLSearchParams({ next: "/.auth/login?next=/" })}`;

/** SIGNED IN AS SOMEONE ELSE, unmissable: whom, who you are, and Stop — signing in again as
 *  yourself (`SIGN_IN_AGAIN`). A collapsed sidebar keeps the eye. */
function ImpersonationMarker({ email, admin }: { email: string; admin: string }) {
  return (
    <form
      method="post"
      action={SIGN_IN_AGAIN}
      role="status"
      className="flex flex-col gap-1.5 rounded-lg border border-amber-300 bg-amber-50 p-2 text-xs text-amber-950 group-data-[collapsible=icon]:border-0 group-data-[collapsible=icon]:p-1.5"
    >
      <div className="flex items-center gap-2">
        <EyeIcon className="size-4 shrink-0" aria-label="Signed in as someone else" />
        <span className="min-w-0 truncate group-data-[collapsible=icon]:hidden">
          Signed in as <strong className="font-semibold">{email}</strong>
        </span>
      </div>
      <span className="truncate text-amber-800 group-data-[collapsible=icon]:hidden">
        You are {admin}
      </span>
      <button
        type="submit"
        className="rounded-md bg-amber-900 px-2 py-1 font-medium text-amber-50 hover:bg-amber-800 group-data-[collapsible=icon]:hidden"
      >
        Stop impersonating
      </button>
    </form>
  );
}

/** The signed-in person; Switch account… (`SIGN_IN_AGAIN`); and sign out: a POST to the app's own
 *  logout, which ends this browser's grant at the issuer. */
function AccountMenu({ email, actions }: { email: string; actions?: ReactNode }) {
  const { isMobile } = useSidebar();
  const logout = useRef<HTMLFormElement>(null);
  const switchAccount = useRef<HTMLFormElement>(null);
  const initials = email.slice(0, 2).toUpperCase();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <SidebarMenuButton
                size="lg"
                className="data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground"
                aria-label="Account"
              >
                <Avatar className="size-8 rounded-lg">
                  <AvatarFallback className="rounded-lg">{initials}</AvatarFallback>
                </Avatar>
                <span className="truncate text-left text-sm font-medium">{email}</span>
                <ChevronsUpDownIcon className="ml-auto" />
              </SidebarMenuButton>
            }
          />
          <DropdownMenuContent
            className="min-w-56 rounded-lg"
            side={isMobile ? "bottom" : "right"}
            align="end"
            sideOffset={4}
          >
            {/* Base UI: a menu label lives inside a group, never bare in the menu */}
            <DropdownMenuGroup>
              <DropdownMenuLabel className="truncate font-normal">{email}</DropdownMenuLabel>
              {actions}
            </DropdownMenuGroup>
            <DropdownMenuSeparator />
            <DropdownMenuGroup>
              <DropdownMenuItem onClick={() => switchAccount.current?.requestSubmit()}>
                <UsersIcon />
                <span>Switch account…</span>
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => {
                  resetPosthog();
                  logout.current?.requestSubmit();
                }}
              >
                <LogOutIcon />
                <span>Sign out</span>
              </DropdownMenuItem>
            </DropdownMenuGroup>
          </DropdownMenuContent>
        </DropdownMenu>
      </SidebarMenuItem>
      {/* the POSTs, outside the menu items so nothing but an item's click submits one */}
      <form ref={switchAccount} method="post" action={SIGN_IN_AGAIN} hidden />
      <form ref={logout} method="post" action="/.auth/logout" hidden />
    </SidebarMenu>
  );
}

// ⌘K in the AppShell: one dialog to switch project or jump to any page the sidebar offers, by
// typing. The rows and the filter are app-shell-palette-entries.ts; this is the dialog, the
// shortcut and the buttons that open it (the sidebar's "Search" row, and the header's on a phone,
// where the sidebar is a sheet).
//
// command.tsx is vendored shadcn (packages/ui/AGENTS.md), so the palette's own look (#2991) lives
// here, in the classNames it passes: flush rows edge to edge instead of upstream's inset, rounded
// ones, and a borderless search row. Two parts are composed here instead: the search row is cmdk's
// input under the palette's own markup, because upstream's CommandInput wraps it in an InputGroup
// that takes no className; and the dialog is Dialog's parts, because upstream's CommandDialog puts
// its sr-only title outside the popup, where a screen reader finds a "Search" heading on every page
// even while the palette is closed.
import { useEffect, useRef, useState, useSyncExternalStore, type MouseEvent } from "react";
import { Command as CommandPrimitive } from "cmdk";
import { CheckIcon, SearchIcon } from "lucide-react";
import {
  filterPaletteEntries,
  withoutProjectLinks,
  type AppPaletteEntry,
  type PaletteEntry,
  type SidebarNavItem,
} from "./app-shell-palette-entries.ts";
import type { AppShellProject } from "./app-shell.tsx";
import { plainLeftClick } from "#/lib/plain-left-click.ts";
import { Button } from "#/components/ui/button.tsx";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandList,
  CommandShortcut,
} from "#/components/ui/command.tsx";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "#/components/ui/dialog.tsx";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "#/components/ui/sidebar.tsx";

type PaletteRow =
  | (PaletteEntry & { kind: "project"; href: string })
  | (PaletteEntry & { kind: "nav"; element: HTMLElement })
  | (PaletteEntry & { kind: "app"; onSelect: () => void });

/** Nothing to subscribe to: the platform does not change under a page. */
const subscribeToNothing = () => () => {};

/** The shortcut as this platform spells it. */
function useShortcutLabel() {
  return useSyncExternalStore(
    subscribeToNothing,
    () => (/Mac|iPhone|iPad/.test(navigator.platform) ? "⌘K" : "Ctrl K"),
    () => "⌘K",
  );
}

/** ⌘K (Ctrl+K off a Mac) anywhere on the page toggles the palette — in a text field too, as the
 *  sidebar's ⌘B does. */
export function usePaletteShortcut(toggle: () => void) {
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (event.defaultPrevented || event.altKey || event.shiftKey) return;
      if (!(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== "k") return;
      event.preventDefault();
      toggle();
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [toggle]);
}

/** The sidebar's "Search" row, above the app's navigation: an icon with a tooltip when the sidebar
 *  is collapsed to its rail. */
export function PaletteSidebarButton({ onOpen }: { onOpen: () => void }) {
  const shortcut = useShortcutLabel();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton type="button" tooltip={`Search (${shortcut})`} onClick={onOpen}>
          <SearchIcon />
          <span>Search</span>
          <kbd className="ml-auto font-sans text-xs text-muted-foreground">{shortcut}</kbd>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

/** The header's search button, on a phone: there the sidebar is a sheet, closed until asked for. */
export function PaletteHeaderButton({ onOpen }: { onOpen: () => void }) {
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      className="md:hidden"
      aria-label="Search"
      title="Search"
      onClick={onOpen}
    >
      <SearchIcon />
    </Button>
  );
}

/** The dialog. `nav` is the sidebar's navigation as it read when the palette opened, null while
 *  closed. A project row is a real link to `projectHref(project)` — a plain click (or Enter) goes
 *  through `onNavigate` when the app has a client router, a modified or middle click opens a tab —
 *  a nav row clicks the sidebar's own element, and an entry the app handed over runs its
 *  `onSelect`. */
export function AppShellPalette({
  nav,
  entries,
  onClose,
  projects,
  activeProjectId,
  projectHref,
  onNavigate,
}: {
  nav: SidebarNavItem[] | null;
  entries: AppPaletteEntry[];
  onClose: () => void;
  projects: AppShellProject[];
  activeProjectId: string | null;
  projectHref: (project: AppShellProject) => string;
  onNavigate: ((href: string, event: MouseEvent<HTMLAnchorElement>) => void) | undefined;
}) {
  return (
    <Dialog
      open={Boolean(nav)}
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent
        showCloseButton={false}
        // near the top, not centred: the list grows and shrinks under the input as you type
        className="top-[12svh] translate-y-0 overflow-hidden p-0 sm:max-w-lg"
      >
        <DialogHeader className="sr-only">
          <DialogTitle>Search</DialogTitle>
          <DialogDescription>Switch project or go to a page</DialogDescription>
        </DialogHeader>
        {nav ? (
          <PaletteBody
            nav={nav}
            entries={entries}
            onClose={onClose}
            projects={projects}
            activeProjectId={activeProjectId}
            projectHref={projectHref}
            onNavigate={onNavigate}
          />
        ) : null}
      </DialogContent>
    </Dialog>
  );
}

/** Mounted per opening, so the query starts empty each time. */
function PaletteBody({
  nav,
  entries,
  onClose,
  projects,
  activeProjectId,
  projectHref,
  onNavigate,
}: {
  nav: SidebarNavItem[];
  entries: AppPaletteEntry[];
  onClose: () => void;
  projects: AppShellProject[];
  activeProjectId: string | null;
  projectHref: (project: AppShellProject) => string;
  onNavigate: ((href: string, event: MouseEvent<HTMLAnchorElement>) => void) | undefined;
}) {
  const [query, setQuery] = useState("");
  const links = useRef(new Map<string, HTMLAnchorElement>());
  const projectRows = projects.map((project): PaletteRow => ({
    kind: "project",
    id: `project:${project.id}`,
    label: project.slug,
    group: "Projects",
    detail: project.org?.name,
    active: project.id === activeProjectId,
    href: projectHref(project),
  }));
  const navRows = withoutProjectLinks(
    nav,
    projects.map((project) => ({
      label: project.slug,
      href: new URL(projectHref(project), location.href).href,
    })),
  ).map(({ element, label, group, detail, active }, index): PaletteRow => ({
    kind: "nav",
    id: `nav:${index}`,
    label,
    group,
    detail,
    active,
    element,
  }));
  const appRows = entries.map((entry, index): PaletteRow => ({
    kind: "app",
    id: `app:${index}`,
    ...entry,
  }));
  const groups = filterPaletteEntries([...navRows, ...appRows, ...projectRows], query);
  return (
    <Command shouldFilter={false} loop className="p-0">
      <div className="flex items-center gap-2 px-3 py-2">
        <SearchIcon className="size-4 shrink-0 text-muted-foreground" aria-hidden />
        <CommandPrimitive.Input
          data-slot="command-input"
          className="flex h-8 w-full min-w-0 bg-transparent text-sm outline-hidden placeholder:text-muted-foreground"
          placeholder="Search projects and pages…"
          aria-label="Search projects and pages"
          value={query}
          onValueChange={setQuery}
        />
      </div>
      <CommandList className="max-h-[min(24rem,60svh)] border-t">
        <CommandEmpty className="text-muted-foreground">Nothing matches.</CommandEmpty>
        {groups.map(({ group, entries }) => (
          <CommandGroup
            key={group}
            heading={group}
            className="p-0 **:[[cmdk-group-heading]]:px-3 **:[[cmdk-group-heading]]:py-2"
          >
            {entries.map((row) => (
              <CommandItem
                key={row.id}
                value={row.id}
                className="rounded-none px-3 py-2 in-data-[slot=dialog-content]:rounded-none!"
                onSelect={() => {
                  if (row.kind === "project") {
                    links.current.get(row.id)?.click();
                    return;
                  }
                  if (row.kind === "app") {
                    onClose();
                    row.onSelect();
                    return;
                  }
                  onClose();
                  row.element.click();
                }}
              >
                {row.kind === "project" ? (
                  <a
                    ref={(link) => {
                      if (link) links.current.set(row.id, link);
                      else links.current.delete(row.id);
                    }}
                    href={row.href}
                    tabIndex={-1}
                    className="flex min-w-0 flex-1 items-center gap-2"
                    onClick={(event) => {
                      // the row's own onSelect would click this again
                      event.stopPropagation();
                      if (!plainLeftClick(event)) return;
                      onClose();
                      onNavigate?.(row.href, event);
                    }}
                  >
                    <PaletteRowLabel row={row} />
                  </a>
                ) : (
                  <PaletteRowLabel row={row} />
                )}
              </CommandItem>
            ))}
          </CommandGroup>
        ))}
      </CommandList>
    </Command>
  );
}

function PaletteRowLabel({ row }: { row: PaletteRow }) {
  return (
    <>
      <span className="truncate">{row.label}</span>
      {row.detail ? (
        <span className="truncate text-xs text-muted-foreground">{row.detail}</span>
      ) : null}
      {row.active ? (
        <CommandShortcut>
          <CheckIcon aria-label="current" />
        </CommandShortcut>
      ) : null}
    </>
  );
}

// What ⌘K in the AppShell offers, and how typing narrows it: the projects the shell's switcher
// lists, and the sidebar's own navigation — read off the rendered sidebar when the palette opens, so
// an app declares its pages once (its `nav`) and the palette offers exactly what the sidebar shows.
// No React here: the filter is a pure function, the reader takes a DOM element.

/** One row of the palette. */
export type PaletteEntry = {
  /** unique across the palette — the row's cmdk value */
  id: string;
  label: string;
  /** the heading the row is listed under */
  group: string;
  /** what the label belongs to (a project's organization, a sub-page's parent) — shown after the
   *  label, and searched with it */
  detail: string | undefined;
  /** the page on screen, or the project it belongs to */
  active: boolean;
};

/** The sidebar's navigation as the palette lists it: every enabled menu button and sub-button in
 *  the sidebar's content, the element itself kept so choosing the row clicks it — the app's own
 *  handler (a client-router `Link`, "New agent") runs exactly as a click in the sidebar would. */
export type SidebarNavItem = Omit<PaletteEntry, "id"> & {
  element: HTMLElement;
  /** the absolute URL, for a link */
  href: string | undefined;
};

/** A row an app hands the palette itself (`AppShell`'s `paletteEntries`): what its sidebar shows
 *  in a way the palette can't read, such as a file tree drawn in its own shadow DOM. Choosing it
 *  runs `onSelect`, which navigates the app's own way. */
export type AppPaletteEntry = Omit<PaletteEntry, "id"> & { onSelect: () => void };

/** Rows under a heading the sidebar gives none (an app's top group of pages). */
export const UNLABELLED_NAV_GROUP = "Pages";

/** The rows that match `query`, grouped under their headings in order of first appearance. A row
 *  matches when every whitespace-separated term occurs, case-insensitively, in its label or
 *  detail; a row whose label starts with the query comes first within its heading, the rest keep
 *  their order. */
export function filterPaletteEntries<Entry extends PaletteEntry>(
  entries: readonly Entry[],
  query: string,
): { group: string; entries: Entry[] }[] {
  const needle = query.trim().toLowerCase();
  const terms = needle.split(/\s+/).filter(Boolean);
  const matching = entries.filter((entry) => {
    const haystack = `${entry.label} ${entry.detail || ""}`.toLowerCase();
    return terms.every((term) => haystack.includes(term));
  });
  const groups = new Map<string, Entry[]>();
  for (const entry of matching)
    groups.set(entry.group, [...(groups.get(entry.group) || []), entry]);
  return [...groups].map(([group, rows]) => ({
    group,
    entries: needle
      ? [
          ...rows.filter((row) => row.label.toLowerCase().startsWith(needle)),
          ...rows.filter((row) => !row.label.toLowerCase().startsWith(needle)),
        ]
      : rows,
  }));
}

/** Reads the sidebar's navigation off `content` (the sidebar's `SidebarContent`): each enabled menu
 *  button and sub-button, labelled by its first text (or its aria-label when it shows none), under
 *  its group's label; its detail is a sub-button's parent item, or the rest of its text. Nothing on a phone, where the
 *  sidebar is a sheet (`data-mobile`): closed, `content` is not mounted (null); open, the palette's
 *  first press is outside it, the sheet closes and unmounts, and a row's element would be detached
 *  by the time it is chosen — a click on it does nothing. */
export function readSidebarNav(content: Element | null): SidebarNavItem[] {
  if (!content || content.closest("[data-mobile]")) return [];
  return [
    ...content.querySelectorAll<HTMLElement>(
      '[data-slot="sidebar-menu-button"], [data-slot="sidebar-menu-sub-button"]',
    ),
  ].flatMap((element) => {
    if (element.matches(':disabled, [aria-disabled="true"]')) return [];
    const [text, ...more] = textBlocks(element);
    const label = text || element.getAttribute("aria-label")?.trim();
    if (!label) return [];
    const group = element.closest('[data-slot="sidebar-group"]');
    const parent =
      element.dataset.slot === "sidebar-menu-sub-button"
        ? element
            .closest('[data-slot="sidebar-menu-sub"]')
            ?.closest('[data-slot="sidebar-menu-item"]')
            ?.querySelector('[data-slot="sidebar-menu-button"]')
        : null;
    return [
      {
        element,
        label,
        group:
          textBlocks(group?.querySelector('[data-slot="sidebar-group-label"]'))[0] ||
          UNLABELLED_NAV_GROUP,
        detail: textBlocks(parent)[0] || more.join(" · ") || undefined,
        active: element.hasAttribute("data-active"),
        href: element instanceof HTMLAnchorElement ? element.href : undefined,
      },
    ];
  });
}

/** The element's text, one entry per element that holds some: a row that stacks a title over a
 *  path (the agents app) reads as `["title", "/agents/…"]`, a group label with a count badge
 *  (`Agents` · `2 active or waiting`) as its name first — the first entry is the label. */
function textBlocks(element: Element | null | undefined) {
  if (!element) return [];
  const blocks = new Map<Node, string>();
  const walker = element.ownerDocument.createTreeWalker(element, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    const holder = node.parentNode || element;
    blocks.set(holder, `${blocks.get(holder) || ""}${node.nodeValue || ""}`);
  }
  return [...blocks.values()].map((text) => text.replace(/\s+/g, " ").trim()).filter(Boolean);
}

/** The sidebar's items less those that are only a link to a project — the dash's organization tree
 *  lists each project by its slug, and the project's own row already offers it. A page at a
 *  project's URL under its own label (the dash's "Overview" is `/projects/<slug>`) stays.
 *  `projects` carry absolute hrefs, as the reader's do. */
export function withoutProjectLinks(
  nav: SidebarNavItem[],
  projects: { label: string; href: string }[],
): SidebarNavItem[] {
  const links = new Set(projects.map((project) => `${project.label} ${project.href}`));
  return nav.filter((item) => !links.has(`${item.label} ${item.href}`));
}
